@dataclass
class StorageIntegration:
    """A storage source (managed or user-configured S3 integration).

    Represents one entry from ``GET /storage``. The ``type`` field
    distinguishes the org's MANAGED bucket from external INTEGRATION
    buckets the user has wired up.
    """

    id: str
    name: str
    path: str
    region: str
    type: str = "INTEGRATION"
    create_time: str | None = None
    update_time: str | None = None
    role_arn: str | None = None
    default_directory: str | None = None
    raw: dict[str, Any] = field(default_factory=dict)

    @property
    def is_managed(self) -> bool:
        """True if this is the org's managed storage source."""
        return self.type == "MANAGED"

    @classmethod
    def from_dict(cls, data: dict[str, Any]) -> StorageIntegration:
        """Deserialize from the Wherobots API JSON format.

        Args:
            data: Dictionary from the API response.

        Returns:
            A new ``StorageIntegration`` instance.
        """
        return cls(
            id=data.get("id", ""),
            name=data.get("name", ""),
            path=data.get("path", ""),
            region=data.get("region", ""),
            type=data.get("type") or "INTEGRATION",
            create_time=data.get("createTime"),
            update_time=data.get("updateTime"),
            role_arn=data.get("roleArn"),
            default_directory=data.get("defaultDirectory"),
            raw=dict(data),
        )

    def to_dict(self) -> dict[str, Any]:
        """Serialize to the Wherobots API JSON format.

        Returns:
            Dict with camelCase keys matching the API contract.
        """
        d: dict[str, Any] = {
            "id": self.id,
            "name": self.name,
            "path": self.path,
            "region": self.region,
            "type": self.type,
        }
        if self.create_time is not None:
            d["createTime"] = self.create_time
        if self.update_time is not None:
            d["updateTime"] = self.update_time
        if self.role_arn is not None:
            d["roleArn"] = self.role_arn
        if self.default_directory is not None:
            d["defaultDirectory"] = self.default_directory
        return d


@dataclass(slots=True, frozen=True)
class TemporaryAwsCredentials:
    """Short-lived AWS STS credentials vended by ``POST /storage/credentials``.

    Scope is determined server-side from the requested S3 path: the
    server picks the right backing bucket (managed / releases /
    matching Storage Integration).

    Security posture:

    - **Masked in repr/str.** ``repr(creds)`` (and therefore ``str(creds)``
      and any f-string interpolation) only show the last 4 characters of
      the access key ID. Secret + session token never appear.
    - **Frozen.** Attribute injection is rejected; ``wipe()`` is the only
      mutator (via ``object.__setattr__`` internally).
    - **No pickle / copy.** ``__reduce__``, ``__copy__``, and
      ``__deepcopy__`` raise ``TypeError`` so creds cannot be silently
      serialized to disk, queues, or another process.
    - **Local eviction via ``wipe()``.** Zeros the secret fields and
      poisons ``expiration`` so any subsequent ``is_expired`` check
      returns ``True``. Python strings are immutable so the original
      bytes may linger on the heap until garbage collection, but this
      drops our last live reference. AWS-side revocation is not
      possible via the SDK; rely on the short TTL (typically 1 h).
    """

    access_key_id: str
    secret_access_key: str
    session_token: str
    expiration: datetime
    region: str

    def __repr__(self) -> str:
        masked = f"***{self.access_key_id[-4:]}" if len(self.access_key_id) > 4 else "***"
        return (
            f"TemporaryAwsCredentials(access_key_id={masked!r}, "
            f"expiration={self.expiration.isoformat()!r}, region={self.region!r})"
        )

    def is_expired(self, leeway_seconds: int = 60) -> bool:
        """True if these creds are within *leeway_seconds* of expiry."""
        deadline = self.expiration - timedelta(seconds=leeway_seconds)
        return datetime.now(timezone.utc) >= deadline

    def wipe(self) -> None:
        """Evict secret material from this object.

        Overwrites ``access_key_id`` / ``secret_access_key`` /
        ``session_token`` with empty strings and forces ``expiration``
        into the past so any post-wipe reuse is detected by
        :meth:`is_expired`. Idempotent; safe to call multiple times.
        """
        # frozen=True blocks normal attribute assignment; reach through
        # ``object.__setattr__`` for the wipe path only.
        object.__setattr__(self, "access_key_id", "")
        object.__setattr__(self, "secret_access_key", "")
        object.__setattr__(self, "session_token", "")
        object.__setattr__(self, "expiration", datetime.now(timezone.utc) - timedelta(seconds=1))

    def __reduce__(self) -> Any:
        raise TypeError(
            "TemporaryAwsCredentials cannot be pickled. "
            "Re-fetch credentials in the consumer process."
        )

    def __copy__(self) -> Any:
        raise TypeError(
            "TemporaryAwsCredentials cannot be copied. "
            "Fetch a fresh set via FilesAPI.get_storage_credentials()."
        )

    def __deepcopy__(self, _memo: dict[int, Any]) -> Any:
        raise TypeError(
            "TemporaryAwsCredentials cannot be deep-copied. "
            "Fetch a fresh set via FilesAPI.get_storage_credentials()."
        )

    @classmethod
    def from_dict(cls, data: dict[str, Any]) -> TemporaryAwsCredentials:
        """Deserialize from the Wherobots API JSON format.

        Args:
            data: Dictionary with camelCase keys from the API response.

        Returns:
            A new ``TemporaryAwsCredentials`` instance.

        Raises:
            ValueError: If any required field is missing/empty, or
                ``expiration`` is unparseable. The exception message
                only references the field NAME — it never contains
                values that could be partial credentials.
        """
        missing = [
            k
            for k in ("accessKeyId", "secretAccessKey", "sessionToken", "expiration", "region")
            if not data.get(k)
        ]
        if missing:
            raise ValueError(f"Credential response is missing required field(s): {missing}")
        raw_exp = data["expiration"]
        # Accept trailing ``Z`` (some servers use it instead of +00:00).
        normalized = raw_exp.replace("Z", "+00:00") if isinstance(raw_exp, str) else ""
        expiration = datetime.fromisoformat(normalized)
        if expiration.tzinfo is None:
            expiration = expiration.replace(tzinfo=timezone.utc)
        return cls(
            access_key_id=data["accessKeyId"],
            secret_access_key=data["secretAccessKey"],
            session_token=data["sessionToken"],
            expiration=expiration,
            region=data["region"],
        )
